using Microsoft.AspNetCore.Identity.EntityFrameworkCore;using Microsoft.EntityFrameworkCore;using OperationsRequests.Domain;
namespace OperationsRequests.Data;public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> o):IdentityDbContext<ApplicationUser>(o){public DbSet<Platform> Platforms=>Set<Platform>();public DbSet<Country> Countries=>Set<Country>();public DbSet<Territory> Territories=>Set<Territory>();public DbSet<Site> Sites=>Set<Site>();public DbSet<TrainingRequest> TrainingRequests=>Set<TrainingRequest>();public DbSet<RequestDecision> RequestDecisions=>Set<RequestDecision>();public DbSet<RequestMessage> RequestMessages=>Set<RequestMessage>();public DbSet<AuditEvent> AuditEvents=>Set<AuditEvent>();protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<TrainingRequest>().Property(x=>x.RowVersion).IsRowVersion();foreach(var e in new[]{typeof(TrainingRequest),typeof(AuditEvent)}){}b.Entity<TrainingRequest>().Property(x=>x.Status).HasConversion<string>();b.Entity<TrainingRequest>().Property(x=>x.Type).HasConversion<string>();b.Entity<TrainingRequest>().Property(x=>x.Priority).HasConversion<string>();b.Entity<AuditEvent>().Property(x=>x.PreviousStatus).HasConversion<string>();b.Entity<AuditEvent>().Property(x=>x.NewStatus).HasConversion<string>();b.Entity<TrainingRequest>().HasIndex(x=>x.RequestNumber).IsUnique();b.Entity<RequestDecision>().HasIndex(x=>new{x.TrainingRequestId,x.Action}).IsUnique().HasFilter("[Action] IN ('Approved','Declined')");b.Entity<TrainingRequest>().HasOne(x=>x.RequestedBy).WithMany().HasForeignKey(x=>x.RequestedById).OnDelete(DeleteBehavior.Restrict);b.Entity<AuditEvent>().HasOne(x=>x.TrainingRequest).WithMany(x=>x.AuditEvents).HasForeignKey(x=>x.TrainingRequestId).OnDelete(DeleteBehavior.Cascade);}}
